arguments.content:
:root {
    --primary: #02838D;
    --primary-hover: #026b73;
    --dark: #231F20;
    --text: #334155;
    --bg: #FFFFFF;
    --bg-light: #F8FAFC;
    --border: #E2E8F0;
    --accent: #F97316; /* coral/amber for CTAs */
    --accent-hover: #ea580c;

    --font-heading: 'Inter', sans-serif;
    --font-body: 'DM Sans', sans-serif;

    --radius-sm: 4px;
    --radius-md: 8px;
    --radius-lg: 16px;
    --radius-full: 9999px;

    --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
    --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);

    --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);

    --container-max: 1200px;
    --spacing-1: 4px;
    --spacing-2: 8px;
    --spacing-3: 16px;
    --spacing-4: 24px;
    --spacing-5: 32px;
    --spacing-6: 48px;
    --spacing-8: 64px;
}

*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html {
    scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
    html {
        scroll-behavior: auto;
    }
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

body {
    font-family: var(--font-body);
    font-size: 16px;
    line-height: 1.6;
    color: var(--text);
    background-color: var(--bg);
    -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-heading);
    color: var(--dark);
    line-height: 1.2;
    margin-bottom: var(--spacing-3);
    font-weight: 600;
}

h1 { font-size: clamp(2rem, 4vw, 3rem); font-weight: 700; }
h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); }
h3 { font-size: 1.25rem; }
h4 { font-size: 1.125rem; }

p { margin-bottom: var(--spacing-3); }

a {
    color: var(--primary);
    text-decoration: none;
    transition: color var(--transition);
}

a:hover, a:focus-visible {
    color: var(--primary-hover);
}

ul, ol { list-style: none; }

img {
    max-width: 100%;
    height: auto;
    display: block;
}

.container {
    width: 100%;
    max-width: var(--container-max);
    margin: 0 auto;
    padding: 0 var(--spacing-4);
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Utilities */
.bg-light { background-color: var(--bg-light); padding: var(--spacing-8) 0; }
.text-center { text-align: center; }
.hidden { display: none !important; }

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--spacing-2) var(--spacing-4);
    border-radius: var(--radius-md);
    font-family: var(--font-heading);
    font-weight: 600;
    text-align: center;
    cursor: pointer;
    transition: all var(--transition);
    min-height: 44px;
    border: 2px solid transparent;
}

.btn-primary {
    background-color: var(--accent);
    color: #fff;
}

.btn-primary:hover, .btn-primary:focus-visible {
    background-color: var(--accent-hover);
    color: #fff;
    transform: translateY(-1px);
}

.btn-outline {
    background-color: transparent;
    color: var(--dark);
    border-color: var(--dark);
}

.btn-outline:hover, .btn-outline:focus-visible {
    background-color: var(--dark);
    color: #fff;
}

button:focus-visible, a:focus-visible, input:focus-visible {
    outline: 3px solid var(--primary);
    outline-offset: 2px;
}

/* Image Placeholders */
.img-placeholder {
    background-color: #E2E8F0;
    width: 100%;
    position: relative;
    overflow: hidden;
}

.img-placeholder::after {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.4), transparent);
    animation: shimmer 2s infinite;
}

@keyframes shimmer {
    0% { transform: translateX(-100%); }
    100% { transform: translateX(100%); }
}

/* Credibility Ticker */
.credibility-ticker {
    background-color: var(--dark);
    color: #fff;
    padding: var(--spacing-2) 0;
    display: flex;
    overflow: hidden;
    white-space: nowrap;
    font-size: 0.875rem;
}

.ticker-content {
    display: flex;
    gap: var(--spacing-6);
    padding-right: var(--spacing-6);
    animation: ticker 30s linear infinite;
}

.ticker-item {
    display: flex;
    align-items: center;
    gap: var(--spacing-2);
}

.ticker-item i {
    width: 16px;
    height: 16px;
    color: var(--primary);
}

@keyframes ticker {
    0% { transform: translateX(0); }
    100% { transform: translateX(-100%); }
}

@media (prefers-reduced-motion: reduce) {
    .ticker-content { animation: none; overflow-x: auto; }
}

/* Header */
.site-header {
    background-color: var(--bg);
    border-bottom: 1px solid var(--border);
    position: sticky;
    top: 0;
    z-index: 100;
}

.header-container {
    max-width: var(--container-max);
    margin: 0 auto;
    padding: var(--spacing-3) var(--spacing-4);
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-family: var(--font-heading);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--primary);
}

.main-nav {
    display: flex;
    align-items: center;
}

.nav-list {
    display: flex;
    gap: var(--spacing-4);
}

.nav-link {
    background: none;
    border: none;
    font-family: var(--font-heading);
    font-size: 1rem;
    font-weight: 500;
    color: var(--dark);
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: var(--spacing-1);
    padding: var(--spacing-2);
    transition: color var(--transition);
}

.nav-link:hover, .nav-link[aria-expanded="true"] {
    color: var(--primary);
}

.nav-link i { width: 16px; height: 16px; transition: transform var(--transition); }
.nav-link[aria-expanded="true"] i { transform: rotate(180deg); }

/* Dropdowns */
.has-dropdown { position: relative; }

.dropdown-menu {
    position: absolute;
    top: 100%;
    left: 0;
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    box-shadow: var(--shadow-lg);
    min-width: 240px;
    opacity: 0;
    visibility: hidden;
    transform: translateY(10px);
    transition: all var(--transition);
    z-index: 110;
    padding: var(--spacing-2) 0;
}

.dropdown-menu.active {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.dropdown-menu ul { display: flex; flex-direction: column; }

.dropdown-menu a {
    display: block;
    padding: var(--spacing-2) var(--spacing-4);
    color: var(--text);
    font-size: 0.9375rem;
}

.dropdown-menu a:hover {
    background-color: var(--bg-light);
    color: var(--primary);
}

.divider {
    height: 1px;
    background-color: var(--border);
    margin: var(--spacing-2) 0;
}

/* Mega Menu */
.mega-menu {
    left: 50%;
    transform: translateX(-50%) translateY(10px);
    width: 100vw;
    max-width: var(--container-max);
}

.mega-menu.active {
    transform: translateX(-50%) translateY(0);
}

.mega-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: var(--spacing-4);
    padding: var(--spacing-4);
}

.header-actions { display: flex; gap: var(--spacing-3); }
.menu-toggle { display: none; background: none; border: none; cursor: pointer; color: var(--dark); }

@media (max-width: 1024px) {
    .nav-list {
        display: none;
        position: absolute;
        top: 100%; left: 0; right: 0;
        background: var(--bg);
        flex-direction: column;
        padding: var(--spacing-4);
        box-shadow: var(--shadow-md);
        border-bottom: 1px solid var(--border);
        gap: 0;
    }
    .nav-list.active { display: flex; }
    .menu-toggle { display: block; }

    .dropdown-menu { position: static; box-shadow: none; border: none; border-left: 2px solid var(--border); margin-left: var(--spacing-4); display: none; transform: none; opacity: 1; visibility: visible; }
    .dropdown-menu.active { display: block; }
    .mega-menu { transform: none; width: auto; }
    .mega-grid { grid-template-columns: 1fr; padding: var(--spacing-2); }
}

/* Main Layout */
#main-content {
    padding-bottom: var(--spacing-8);
}

/* Hero Section */
.hero-section {
    padding: var(--spacing-6) 0;
}

.hero-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: var(--spacing-6);
}

.hero-main {
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    display: flex;
    flex-direction: column;
}

.hero-img {
    aspect-ratio: 16/9;
}

.hero-content {
    padding: var(--spacing-5);
    background: var(--bg);
}

.category-label {
    font-size: 0.875rem;
    font-weight: 600;
    color: var(--primary);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--spacing-2);
    display: inline-block;
}

.badge {
    display: inline-flex;
    background-color: var(--bg-light);
    border: 1px solid var(--border);
    padding: var(--spacing-1) var(--spacing-3);
    border-radius: var(--radius-full);
    font-size: 0.875rem;
    font-weight: 500;
    margin-top: var(--spacing-3);
}

.trending-sidebar h2 { font-size: 1.5rem; margin-bottom: var(--spacing-4); padding-bottom: var(--spacing-2); border-bottom: 2px solid var(--border); }
.trending-list { display: flex; flex-direction: column; gap: var(--spacing-4); }

.trending-link { display: block; color: inherit; }
.trending-link:hover h4 { color: var(--primary); }
.trending-link h4 { font-size: 1.125rem; margin: 0; line-height: 1.4; transition: color var(--transition); }

@media (max-width: 768px) {
    .hero-grid { grid-template-columns: 1fr; }
}

/* Newsletter CTA */
.newsletter-cta { background-color: var(--primary); color: #fff; padding: var(--spacing-6) 0; }
.newsletter-content { display: grid; grid-template-columns: 1fr 1fr; gap: var(--spacing-6); align-items: center; }
.newsletter-text h2 { color: #fff; margin-bottom: var(--spacing-2); }
.newsletter-text p { margin-bottom: 0; opacity: 0.9; }

.newsletter-form { display: flex; flex-direction: column; gap: var(--spacing-2); }
.input-group { display: flex; gap: var(--spacing-2); }
.input-group input {
    flex: 1;
    padding: var(--spacing-2) var(--spacing-3);
    border: none;
    border-radius: var(--radius-md);
    font-family: var(--font-body);
    font-size: 1rem;
    min-height: 44px;
}
.newsletter-form small { font-size: 0.75rem; opacity: 0.8; }

@media (max-width: 768px) {
    .newsletter-content { grid-template-columns: 1fr; }
    .input-group { flex-direction: column; }
}

/* Health Topics Carousel */
.health-topics { padding: var(--spacing-8) 0; }
.section-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--spacing-5); }
.view-all { font-weight: 600; display: inline-flex; align-items: center; gap: var(--spacing-1); }
.view-all::after { content: "→"; font-family: 'lucide'; transition: transform var(--transition); }
.view-all:hover::after { transform: translateX(4px); }

.carousel-container { position: relative; display: flex; align-items: center; }
.carousel-btn {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    background: var(--bg);
    border: 1px solid var(--border);
    width: 44px; height: 44px;
    border-radius: var(--radius-full);
    display: flex; align-items: center; justify-content: center;
    cursor: pointer;
    box-shadow: var(--shadow-sm);
    z-index: 10;
    color: var(--dark);
    transition: all var(--transition);
}
.carousel-btn:hover { background: var(--primary); color: #fff; border-color: var(--primary); }
.carousel-btn.prev { left: -22px; }
.carousel-btn.next { right: -22px; }

.carousel-track {
    display: flex; gap: var(--spacing-4); overflow-x: auto;
    scroll-snap-type: x mandatory;
    scroll-behavior: smooth;
    scrollbar-width: none;
    padding-bottom: var(--spacing-2);
}
.carousel-track::-webkit-scrollbar { display: none; }

.topic-card {
    flex: 0 0 calc(33.333% - var(--spacing-4));
    display: flex; flex-direction: column; align-items: center; text-align: center; gap: var(--spacing-3);
    scroll-snap-align: start; color: inherit;
}
.topic-img {
    width: 120px; height: 120px; border-radius: var(--radius-full);
    background-color: var(--bg-light); border: 1px solid var(--border);
    transition: transform var(--transition), box-shadow var(--transition);
}
.topic-card:hover .topic-img { transform: scale(1.05); box-shadow: var(--shadow-md); border-color: var(--primary); }
.topic-card span { font-weight: 600; font-family: var(--font-heading); }

@media (max-width: 1024px) { .topic-card { flex: 0 0 calc(50% - var(--spacing-4)); } }
@media (max-width: 600px) { .topic-card { flex: 0 0 80%; } .carousel-btn { display: none; } }

/* Health Tools */
.health-tools { padding: var(--spacing-8) 0; }
.tools-grid { display: grid; grid-template-columns: 1fr 1fr; gap: var(--spacing-6); }

.tools-card {
    background: var(--bg); padding: var(--spacing-5);
    border-radius: var(--radius-lg); box-shadow: var(--shadow-sm); border: 1px solid var(--border);
}
.tools-card h2 { font-size: 1.75rem; }
.tools-list { margin-top: var(--spacing-5); display: flex; flex-direction: column; gap: var(--spacing-4); }
.tools-list li { display: flex; gap: var(--spacing-3); align-items: flex-start; }

.tool-icon {
    background: var(--bg-light); color: var(--primary);
    width: 48px; height: 48px; border-radius: var(--radius-md);
    display: flex; align-items: center; justify-content: center; flex-shrink: 0;
}

.tools-list strong { display: block; font-family: var(--font-heading); color: var(--dark); font-size: 1.125rem; margin-bottom: 4px; }
.tools-list span { display: block; font-size: 0.9375rem; color: var(--text); }
.inline-link { display: inline-block; margin-top: var(--spacing-1); font-weight: 500; }

@media (max-width: 768px) { .tools-grid { grid-template-columns: 1fr; } }

/* Recommended Reads */
.recommended-reads { padding: var(--spacing-8) 0; }
.tabs-container { margin-bottom: var(--spacing-5); border-bottom: 1px solid var(--border); }
.tabs-scroll { display: flex; overflow-x: auto; gap: var(--spacing-4); scrollbar-width: none; }
.tabs-scroll::-webkit-scrollbar { display: none; }

.tab-btn {
    background: none; border: none; border-bottom: 2px solid transparent;
    padding: var(--spacing-3) var(--spacing-1);
    font-family: var(--font-heading); font-size: 1.125rem; font-weight: 600;
    color: var(--text); cursor: pointer; white-space: nowrap; transition: all var(--transition);
}
.tab-btn:hover { color: var(--primary); }
.tab-btn.active { color: var(--primary); border-bottom-color: var(--primary); }

.articles-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--spacing-6); }

.article-card {
    display: flex; flex-direction: column;
    border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden;
    transition: box-shadow var(--transition);
    cursor: pointer;
}
.article-card:hover { box-shadow: var(--shadow-md); }
.article-img { aspect-ratio: 3/2; }
.article-content { padding: var(--spacing-4); background: var(--bg); flex: 1; }
.article-content h4 { margin: 0; font-size: 1.125rem; }

/* Trust Pillars */
.trust-pillars { padding: var(--spacing-8) 0; background: var(--dark); color: #fff; }
.trust-pillars h2 { color: #fff; margin-bottom: var(--spacing-6); }
.pillars-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: var(--spacing-6); }

.pillar-card { text-align: center; display: flex; flex-direction: column; align-items: center; }
.pillar-icon {
    width: 64px; height: 64px; border-radius: var(--radius-full);
    background: rgba(255,255,255,0.1); color: var(--primary);
    display: flex; align-items: center; justify-content: center;
    margin-bottom: var(--spacing-4);
}
.pillar-icon i { width: 32px; height: 32px; color: #fff; }
.pillar-card h3 { color: #fff; margin-bottom: var(--spacing-2); font-size: 1.25rem; }
.pillar-card p { opacity: 0.9; margin: 0; font-size: 0.9375rem; }

/* Featured Programs & Latest Videos */
.featured-programs { padding: var(--spacing-8) 0; }
.programs-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: var(--spacing-5); }
.program-card {
    display: flex; flex-direction: column; border-radius: var(--radius-md); overflow: hidden;
    box-shadow: var(--shadow-sm); transition: transform var(--transition); color: inherit;
}
.program-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.program-img { aspect-ratio: 4/3; }
.program-content { padding: var(--spacing-3); background: var(--bg); border: 1px solid var(--border); border-top: none; border-radius: 0 0 var(--radius-md) var(--radius-md); }
.program-content h3 { margin: 0; font-size: 1.125rem; text-align: center; }

.latest-videos { padding: var(--spacing-8) 0; }
.videos-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: var(--spacing-6); }
.video-card { cursor: pointer; }
.video-card:hover h3 { color: var(--primary); }
.video-img { aspect-ratio: 16/9; border-radius: var(--radius-md); position: relative; margin-bottom: var(--spacing-3); display: flex; align-items: center; justify-content: center; }
.play-btn {
    width: 64px; height: 64px; border-radius: var(--radius-full);
    background: rgba(0,0,0,0.6); color: #fff; border: none;
    display: flex; align-items: center; justify-content: center; cursor: pointer;
    transition: background var(--transition), transform var(--transition);
}
.video-card:hover .play-btn { background: var(--primary); transform: scale(1.1); }
.video-content h3 { font-size: 1.125rem; margin: 0; transition: color var(--transition); }

/* Footer */
.site-footer { background: var(--dark); color: #fff; padding: var(--spacing-8) 0 var(--spacing-4); font-size: 0.875rem; }
.footer-grid { display: grid; grid-template-columns: 1fr 2fr; gap: var(--spacing-8); margin-bottom: var(--spacing-6); padding-bottom: var(--spacing-6); border-bottom: 1px solid rgba(255,255,255,0.1); }
.footer-newsletter h3 { color: #fff; font-size: 1.5rem; margin-bottom: var(--spacing-3); }
.footer-newsletter p { opacity: 0.8; margin-bottom: var(--spacing-4); }

.footer-links { display: flex; justify-content: space-around; gap: var(--spacing-4); }
.footer-links ul { display: flex; flex-direction: column; gap: var(--spacing-3); }
.footer-links a { color: rgba(255,255,255,0.8); }
.footer-links a:hover { color: #fff; text-decoration: underline; }

.footer-bottom { display: flex; justify-content: space-between; align-items: flex-end; gap: var(--spacing-4); }
.legal { max-width: 700px; opacity: 0.6; font-size: 0.75rem; }

.social-links { display: flex; gap: var(--spacing-3); }
.social-links a { color: rgba(255,255,255,0.8); width: 40px; height: 40px; display: flex; align-items: center; justify-content: center; border-radius: var(--radius-full); background: rgba(255,255,255,0.1); transition: all var(--transition); }
.social-links a:hover { background: var(--primary); color: #fff; }

@media (max-width: 768px) {
    .footer-grid { grid-template-columns: 1fr; }
    .footer-links { justify-content: flex-start; gap: var(--spacing-8); }
    .footer-bottom { flex-direction: column; align-items: flex-start; gap: var(--spacing-4); }
}

document.addEventListener('DOMContentLoaded', () => {
    // Initialize Lucide icons
    lucide.createIcons();

    // 1. Mobile Menu Toggle
    const menuToggle = document.querySelector('.menu-toggle');
    const navList = document.getElementById('nav-list');

    if (menuToggle && navList) {
        menuToggle.addEventListener('click', () => {
            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
            menuToggle.setAttribute('aria-expanded', !isExpanded);
            navList.classList.toggle('active');
        });
    }

    // 2. Dropdown Menus
    const dropdownLinks = document.querySelectorAll('.has-dropdown > .nav-link');

    dropdownLinks.forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const parent = link.parentElement;
            const dropdown = parent.querySelector('.dropdown-menu');
            const isExpanded = link.getAttribute('aria-expanded') === 'true';

            // Close all others
            document.querySelectorAll('.has-dropdown').forEach(item => {
                if (item !== parent) {
                    item.querySelector('.nav-link').setAttribute('aria-expanded', 'false');
                    const menu = item.querySelector('.dropdown-menu');
                    if (menu) menu.classList.remove('active');
                }
            });

            // Toggle current
            link.setAttribute('aria-expanded', !isExpanded);
            if (dropdown) {
                dropdown.classList.toggle('active');
            }
        });
    });

    // Close dropdowns when clicking outside
    document.addEventListener('click', (e) => {
        if (!e.target.closest('.has-dropdown')) {
            document.querySelectorAll('.has-dropdown').forEach(item => {
                item.querySelector('.nav-link').setAttribute('aria-expanded', 'false');
                const menu = item.querySelector('.dropdown-menu');
                if (menu) menu.classList.remove('active');
            });
        }
    });

    // 3. Recommended Reads Tabs
    const tabBtns = document.querySelectorAll('.tab-btn');
    const articles = document.querySelectorAll('.article-card');

    tabBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            // Remove active from all tabs
            tabBtns.forEach(t => {
                t.classList.remove('active');
                t.setAttribute('aria-selected', 'false');
            });

            // Set active to clicked tab
            btn.classList.add('active');
            btn.setAttribute('aria-selected', 'true');

            const category = btn.getAttribute('data-category');

            // Show/hide articles
            articles.forEach(article => {
                if (article.getAttribute('data-category') === category) {
                    article.classList.remove('hidden');
                } else {
                    article.classList.add('hidden');
                }
            });
        });
    });

    // 4. Health Topics Carousel
    const track = document.getElementById('topics-track');
    const prevBtn = document.querySelector('.carousel-btn.prev');
    const nextBtn = document.querySelector('.carousel-btn.next');

    if (track && prevBtn && nextBtn) {
        const scrollAmount = 300; // Approx card width + gap

        prevBtn.addEventListener('click', () => {
            track.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
        });

        nextBtn.addEventListener('click', () => {
            track.scrollBy({ left: scrollAmount, behavior: 'smooth' });
        });
    }

    // 5. Newsletter Forms
    const handleNewsletterSubmit = (formId, feedbackId) => {
        const form = document.getElementById(formId);
        const feedback = document.getElementById(feedbackId);

        if (form && feedback) {
            form.addEventListener('submit', (e) => {
                e.preventDefault();
                const emailInput = form.querySelector('input[type="email"]');
                if (emailInput.value) {
                    feedback.textContent = 'Thanks for subscribing! Check your inbox to confirm.';
                    feedback.style.color = 'var(--accent)';
                    feedback.style.marginTop = 'var(--spacing-2)';
                    emailInput.value = ''; // clear input
                }
            });
        }
    };

    handleNewsletterSubmit('newsletter-form-main', 'feedback-main');
    handleNewsletterSubmit('newsletter-form-footer', 'feedback-footer');
});

